<script setup lang="ts">
import RepairAuthorizationReview from './RepairAuthorizationReview.vue'
import QuoteReviewWorkbench from './QuoteReviewWorkbench.vue'
import {reviewLines,reviewPayload,reviewCalculation,moneyCents,yuan,type ReviewLine} from './quote-review'
import QuoteLines from '@/shared/ui/QuoteLines.vue'
import RecordList from '@/shared/ui/RecordList.vue'
import RecognitionSource from '../materials/RecognitionSource.vue'
import type {Workflow} from '../workorders/workflow'
import {computed,onActivated,onDeactivated,onMounted,onUnmounted,ref,watch} from 'vue'
import {ElButton,ElDialog} from 'element-plus'
import {currentUser,httpClient} from '@/shared/http/client'
import {formalPayload,quotationApi,type QuoteCase} from './quotation'
const props=defineProps<{caseId:string;refreshToken?:number;workflow:Workflow;claimNo?:string;insuranceCompany?:string;vehiclePlate?:string;vehicleVin?:string}>(),emit=defineEmits<{changed:[];draft:[value:{assessment:string;markup:string;mode:string}|undefined]}>(),api=quotationApi(httpClient,props.caseId)
const cs=computed(()=>currentUser.value?.roles.includes('CUSTOMER_SERVICE'))
const data=ref<QuoteCase>(),busy=ref(false),message=ref(''),mode=ref<'FIXED_AMOUNT'|'PERCENTAGE'>('PERCENTAGE'),markup=ref('0.00'),assessment=ref(''),historyType=ref('EVENT'),historyPage=ref(1),historyTotal=ref(0),history=ref('')
const authorizationReview=ref<InstanceType<typeof RepairAuthorizationReview>>()
const assessmentDialog=ref(false),pendingAssessment=ref<{amount:string;version:number}>()
const vehicleIdentity=computed(()=>props.vehiclePlate||props.vehicleVin||'未填写')
const assessmentValue=computed(()=>assessment.value.trim())
const reviewedLines=ref<ReviewLine[]>([]),reviewBasis=ref<{id?:string;version:number}>()
const reviewStale=computed(()=>Boolean(dirty.value&&data.value&&reviewBasis.value&&(reviewBasis.value.id!==data.value.rawQuote?.id||reviewBasis.value.version!==data.value.version)))
const pending=ref<{body:string;key:string}>()
const dirty=ref(false),correction=ref(''),amountInput=ref<HTMLInputElement>()
watch(()=>[dirty.value,assessment.value,markup.value,mode.value],()=>emit('draft',dirty.value?{assessment:assessment.value,markup:markup.value,mode:mode.value}:undefined))
const reviewPreview=ref(false),receiptError=ref('')
const previewAvailable=computed(()=>import.meta.env.DEV&&cs.value&&props.workflow.currentNode==='SHOP_QUOTE')
const authorizing=computed(()=>props.workflow.currentNode==='REPAIR'&&props.workflow.status==='WAITING_REPAIR_AUTHORIZATION')
const editingNode=computed(()=>reviewPreview.value?'QUOTE_REVIEW':correction.value||(authorizing.value?'REPAIR_AUTHORIZATION':props.workflow.currentNode))
const assessmentIssue=computed(()=>editingNode.value!=='INSURER_ASSESSMENT'?'':!/^(?:0|[1-9][0-9]{0,35})(?:\.[0-9]{1,2})?$/.test(assessmentValue.value)?'请填写有效最终核损金额，最多2位小数':'')
const shopReceipts=computed(()=>[{category:'SHOP_QUOTE',name:'报价原件'},{category:'ARRIVAL_PHOTO',name:'到店照'}].map(item=>({...item,received:props.workflow.materials.some(m=>m.category===item.category&&m.shopUploaded)})))
let receiptTimer:ReturnType<typeof setTimeout>|undefined,receiptEpoch=0
function stopReceiptPolling(){receiptEpoch++;clearTimeout(receiptTimer)}
function startReceiptPolling(){stopReceiptPolling();if(props.workflow.currentNode==='SHOP_QUOTE')receiptTimer=setTimeout(()=>void pollReceipt(),8000)}
async function pollReceipt(){
 const epoch=receiptEpoch
 try{if(!document.hidden&&!busy.value&&props.workflow.currentNode==='SHOP_QUOTE'){
  const latest=(await httpClient.get<{data:Workflow}>(`/work-orders/${props.caseId}/workflow`)).data.data
  if(epoch!==receiptEpoch)return
  receiptError.value=''
  if(latest.currentNode!==props.workflow.currentNode||JSON.stringify(latest.materials)!==JSON.stringify(props.workflow.materials))emit('changed')
 }}catch{if(epoch===receiptEpoch)receiptError.value='自动刷新暂不可用，请点击页面刷新。'}
 finally{if(epoch===receiptEpoch&&props.workflow.currentNode==='SHOP_QUOTE')receiptTimer=setTimeout(()=>void pollReceipt(),8000)}
}
function openReviewPreview(){if(previewAvailable.value){reviewPreview.value=true;message.value=''}}
const title=computed(()=>reviewPreview.value?'报价审核预览':props.workflow.nodes.find(n=>n.key===props.workflow.currentNode)?.label??'报价记录')
async function load(){const next=await api.get();if(dirty.value&&data.value&&next.version!==data.value.version)message.value='报价或核损依据已变化，已保留输入，请重新核对当前版本';data.value=next;if(!dirty.value){if(next.formalQuote&&(next.formalQuote.mode==='PERCENTAGE'||next.formalQuote.mode==='FIXED_AMOUNT')){markup.value=next.formalQuote.markupValue;mode.value=next.formalQuote.mode}reviewBasis.value={id:next.rawQuote?.id,version:next.version};reviewedLines.value=reviewLines(next.formalQuote?.rawQuoteId===next.rawQuote?.id&&next.formalQuote?.reviewedLines?next.formalQuote.reviewedLines:next.rawQuote?.lines??[])}if(!dirty.value&&data.value.assessment)assessment.value=data.value.assessment.amount}
async function run(action:()=>Promise<void>){if(busy.value)return;busy.value=true;message.value='';try{await action()}catch(e){message.value=e instanceof Error?e.message:'操作失败'}finally{busy.value=false}}
async function post(path:string,body:unknown){const serialized=JSON.stringify({path,body});if(pending.value?.body!==serialized)pending.value={body:serialized,key:crypto.randomUUID()};data.value=await api.post(path,body,pending.value.key);pending.value=undefined;dirty.value=false;message.value='已保存';correction.value='';emit('changed')}
async function proceed(){
 if(reviewPreview.value)throw Error('当前为只读预览，请等待网点正式提交报价')
 const latest=(await httpClient.get<{data:Workflow}>(`/work-orders/${props.caseId}/workflow`)).data.data
 if((!latest.canAct&&!correction.value)||latest.currentNode!==props.workflow.currentNode)throw Error('任务已变化，请刷新当前节点')
 if(!data.value)return
 if(editingNode.value==='QUOTE_REVIEW'){if(reviewStale.value)throw Error('报价版本已变化，请放弃当前修正并载入新报价后重新核对');reviewCalculation(reviewedLines.value,markup.value,mode.value);await post('formal-quotes',{...formalPayload(data.value.version,data.value.rawQuote?.id??'',mode.value,markup.value.trim()),reviewedLines:reviewPayload(reviewedLines.value)})}
 else if(editingNode.value==='INSURER_ASSESSMENT'){
  if(!/^(?:0|[1-9][0-9]{0,35})(?:\.[0-9]{1,2})?$/.test(assessmentValue.value)){amountInput.value?.focus();throw Error('请填写有效最终核损金额，最多2位小数')}
  pendingAssessment.value={amount:yuan(moneyCents(assessmentValue.value)),version:data.value.version};assessmentDialog.value=true
 }else if(latest.currentNode==='REPAIR'&&latest.status==='WAITING_REPAIR_AUTHORIZATION'){const kind=data.value.gate.insurerConfirmationRecorded?'CUSTOMER_SERVICE':'INSURER';if(kind==='CUSTOMER_SERVICE'&&!authorizationReview.value)throw Error('请先核对正式报价与最终核损金额');await post(`confirmations/${kind}`,{expectedVersion:data.value.version,...(kind==='CUSTOMER_SERVICE'?authorizationReview.value!.confirmation():{})})}
}
async function confirmAssessment(){
 if(!pendingAssessment.value||!assessmentDialog.value)return
 const latest=(await httpClient.get<{data:Workflow}>(`/work-orders/${props.caseId}/workflow`)).data.data
 if((!latest.canAct&&!correction.value)||latest.currentNode!==props.workflow.currentNode)throw Error('任务已变化，请刷新当前节点')
 await post('assessments',{expectedVersion:pendingAssessment.value.version,amount:pendingAssessment.value.amount})
 assessmentDialog.value=false;pendingAssessment.value=undefined
}
function cancelAssessment(){assessmentDialog.value=false;pendingAssessment.value=undefined}
async function loadHistory(){const result=await api.history(historyType.value,historyPage.value);historyTotal.value=result.total;history.value=JSON.stringify(result.records,null,2)}
async function exportFile(kind:'pdf'|'csv'){if(!data.value?.formalQuote)return;const blob=kind==='pdf'?await api.pdf(data.value.formalQuote.id):await api.export(data.value.formalQuote.id),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`formal-quote-v${data.value.formalQuote.version}.${kind}`;a.click();URL.revokeObjectURL(url)}
onMounted(async()=>{startReceiptPolling();await run(load)});onDeactivated(stopReceiptPolling);onUnmounted(stopReceiptPolling);onActivated(async()=>{startReceiptPolling();await run(load)});watch(()=>props.refreshToken,()=>void run(load));watch(()=>props.workflow.currentNode,()=>{reviewPreview.value=false;startReceiptPolling();if(dirty.value)message.value='流程已更新，未提交信息保留，请核对当前任务';void run(load)})
</script>
<template><section class="quotation"><h2>{{ title }}</h2><p v-if="message&&!data" role="alert" class="inline-error">{{ message }} <button v-if="!data" @click="run(load)">重试</button></p><template v-if="data"><p v-if="reviewPreview" role="status" class="preview-note">开发预览 · 案件仍在等待网点报价，此页只读。</p><section v-if="workflow.currentNode==='SHOP_QUOTE'&&!reviewPreview" data-reading="网点材料"><h3>网点材料</h3><ul class="gate-list receipt-list"><li v-for="item in shopReceipts" :key="item.category"><span>{{ item.name }}</span><strong :class="item.received?'complete':'missing'"><svg viewBox="0 0 20 20" aria-hidden="true"><path :d="item.received?'M4 10l4 4 8-8':'M5 5l10 10M15 5L5 15'"/></svg>{{ item.received?'网点已上传':'等待网点上传' }}</strong></li><li><span>报价提交</span><strong class="waiting">等待网点确认提交</strong></li></ul><p role="status">网点提交后自动进入报价审核。</p><p v-if="receiptError" role="alert" class="inline-error">{{ receiptError }}</p></section><section v-if="editingNode==='INSURER_ASSESSMENT'" class="assessment-case" data-reading="案件信息"><h3>案件信息</h3><div class="assessment-facts"><label>报案号<input :value="claimNo||'未填写'" readonly/></label><label>保险公司<input :value="insuranceCompany||'未填写'" readonly/></label><label class="vehicle-identity">车牌号/车架号<input :value="vehicleIdentity" readonly/></label></div></section><section v-if="editingNode!=='QUOTE_REVIEW'&&workflow.currentNode!=='SHOP_QUOTE'&&!authorizing" data-reading="报价依据"><h3>报价依据</h3><details v-if="data.rawQuote" :open="editingNode==='INSURER_ASSESSMENT'"><summary>网点报价 <strong class="quote-total">{{ data.rawQuote.total }} <small>元</small></strong> · 查看明细与原件</summary><QuoteLines :lines="data.rawQuote.lines"/><RecognitionSource :case-id="caseId" :business-id="data.rawQuote.id"/></details><p v-else>等待网点提交报价原件和核对信息。</p><details v-if="data.formalQuote" :open="editingNode==='INSURER_ASSESSMENT'"><summary>正式报价 <strong class="quote-total">{{ data.formalQuote.total }} <small>元</small></strong></summary><p>{{ data.formalQuote.reviewedLines?'核对合计':'网点合计' }} {{ data.formalQuote.originalTotal }} · 加价 {{ data.formalQuote.markupAmount }} 元</p><QuoteLines :lines="data.formalQuote.lines" formal/><button :disabled="busy" @click="run(()=>exportFile('pdf'))">下载报价单</button><button :disabled="busy" @click="run(()=>exportFile('csv'))">导出明细</button></details></section>
<QuoteReviewWorkbench v-if="editingNode==='QUOTE_REVIEW'" :originals="data.rawQuote?.originals??[]" :lines="reviewedLines" :value="markup" :mode="mode" :readonly="reviewPreview||busy||!cs||reviewStale" @lines="reviewedLines=$event;dirty=true" @value="markup=$event;dirty=true" @mode="mode=$event;markup='0.00';dirty=true"/>

<section v-if="editingNode==='INSURER_ASSESSMENT'" class="assessment-entry" data-reading="核损信息"><h3>核损信息</h3><label for="final-assessment-amount">最终核损金额（元）<input id="final-assessment-amount" ref="amountInput" v-model="assessment" :disabled="!cs||busy||assessmentDialog" inputmode="decimal" autocomplete="off" placeholder="请输入最终核损金额" @input="dirty=true"/></label><p v-if="data.assessment">已录入 {{ data.assessment.amount }} 元</p></section>
<ElDialog v-model="assessmentDialog" title="确认核损金额" width="min(460px, 94vw)" append-to-body :close-on-click-modal="!busy" :close-on-press-escape="!busy" :show-close="!busy"><div class="assessment-confirmation"><p>最终核损金额</p><strong>{{ pendingAssessment?.amount }} <small>元</small></strong><p>确认后保存此金额，并进入下一步。</p><p v-if="message" role="alert" class="inline-error">{{ message }}</p></div><template #footer><ElButton :disabled="busy" @click="cancelAssessment">取消</ElButton><ElButton type="primary" :loading="busy" @click="run(confirmAssessment)">确认</ElButton></template></ElDialog>
<details v-if="cs&&data.formalQuote&&['WAITING_INSURER_ASSESSMENT','WAITING_REPAIR_AUTHORIZATION'].includes(data.status)"><summary>修正资料</summary><p>修正后原确认失效，需重新确认。</p><button :disabled="busy" @click="correction='QUOTE_REVIEW'">修正报价</button><button :disabled="busy" @click="correction='INSURER_ASSESSMENT'">修正核损</button><button v-if="correction" @click="correction=''">取消修正</button></details><RepairAuthorizationReview v-if="authorizing&&!correction" ref="authorizationReview" :case-id="caseId" :quote="data" :readonly="busy||!cs||data.authorized"/><RecognitionSource v-if="data.assessment?.lossFileId&&!authorizing" :case-id="caseId" :business-id="data.assessment.id"/><section v-if="authorizing" data-reading="授权条件"><h3>授权条件</h3><ul class="gate-list"><li v-for="item in [{key:'finalAssessmentAmountRecorded',name:'最终核损金额'},{key:'insurerConfirmationRecorded',name:'保险公司确认'},{key:'customerServiceConfirmationRecorded',name:'客服确认'}]" :key="item.key"><span>{{ item.name }}</span><strong :class="data.gate[item.key as keyof typeof data.gate]?'complete':'missing'">{{ data.gate[item.key as keyof typeof data.gate]?'已满足':'待办理' }}</strong></li></ul><p v-if="data.authorized">等待网点开始维修。</p></section>
<details v-if="workflow.currentNode!=='SHOP_QUOTE'||reviewPreview"><summary>版本记录</summary><select v-model="historyType"><option value="RAW">网点报价</option><option value="FORMAL">正式报价</option><option value="ASSESSMENT">核损</option><option value="CONFIRMATION">确认</option><option value="EVENT">变更记录</option></select><button :disabled="busy" @click="run(loadHistory)">查询</button><RecordList :value="history"/><button :disabled="busy||historyPage===1" @click="historyPage--;run(loadHistory)">上一页</button><span>第 {{ historyPage }} 页 · 共 {{ historyTotal }} 条</span><button :disabled="busy||historyPage*20>=historyTotal" @click="historyPage++;run(loadHistory)">下一页</button></details>
<footer class="workflow-action"><div class="action-feedback"><p v-if="message" role="alert" class="inline-error">{{ message }} <button v-if="reviewStale" @click="run(async()=>{dirty=false;await load()})">放弃修正并载入新报价</button></p><span role="status">{{ reviewPreview?'开发预览 · 真实流程未推进':workflow.canAct?(assessmentIssue||'核对信息后继续'):workflow.actorRole==='REPAIR_SHOP'?'等待网点处理':'当前仅查看' }}</span></div><button v-if="previewAvailable&&!reviewPreview" :disabled="busy" @click="openReviewPreview">预览报价审核</button><button v-if="reviewPreview" @click="reviewPreview=false">返回网点报价</button><button v-if="!reviewPreview&&(workflow.canAct||correction)&&cs" class="primary" :disabled="busy||Boolean(assessmentIssue)" @click="run(proceed)">{{ busy?'正在保存…':!correction&&authorizing?(data.gate.insurerConfirmationRecorded?'客服确认':'记录保险确认'):'继续' }}</button></footer></template><div v-else-if="busy" class="quote-skeleton" aria-busy="true"><span/><span/><span/></div></section></template>
<style scoped>.quotation{display:flex;flex-direction:column;padding:0;min-width:0}.quotation>*{order:3}.quotation>h2,.quotation>.inline-error,.quotation>.preview-note{order:0}.quotation>section[data-reading="核损信息"],.quotation>section[data-reading="审核信息"],.quotation>section[data-reading="授权条件"],.quotation>section[data-reading="最终价格核对"]{order:1}.quotation>section[data-reading="案件信息"]{order:1}.quotation>section[data-reading="报价依据"]{order:2}.quotation>section.assessment-entry{order:3}.quotation>.workflow-action{order:9}.quotation h2{font-size:24px;margin:0 0 24px}.quotation h3{font-size:17px;margin:0 0 14px}.quotation section{padding:18px 0;border-top:1px solid #dce5e4;scroll-margin-top:180px}.quotation label{display:grid;gap:8px;margin:16px 0;font-size:13px}.quotation input,.quotation select{padding:10px;border:1px solid #bccccc;border-radius:6px;max-width:100%;font:inherit}.quotation button{margin:6px 8px 6px 0}.quotation details{margin:18px 0}.quotation summary{cursor:pointer}.quotation p{color:#536a6b;font-size:13px}.preview-note{padding:12px;border:1px solid #e5cc8d;border-radius:8px;background:#fff9e9;color:#755814!important}.receipt-list strong{display:inline-flex;align-items:center;gap:6px;font-size:13px}.receipt-list svg{width:16px;height:16px;fill:none;stroke:currentColor;stroke-width:2}.waiting{color:#80610b}.gate-list{padding:0;list-style:none}.gate-list li{display:flex;justify-content:space-between;gap:16px;border-bottom:1px solid #dce5e4;padding:14px 0}.complete{color:#236b4b}.missing,.inline-error{color:#a7313c}.workflow-action{position:sticky;bottom:16px;display:flex;justify-content:space-between;align-items:center;gap:16px;margin:32px -12px 0;padding:14px 18px;border:1px solid #fff;background:#f5faf8;box-shadow:inset 0 1px #fff,0 6px 24px #30595112;border-radius:12px;z-index:2}.workflow-action span{font-size:12px;color:#536a6b}.workflow-action .primary{background:#42685f;color:#fff;border-color:#42685f;min-width:100px}.workflow-action .action-feedback{min-width:0}.workflow-action .inline-error{color:#a7313c;margin:0 0 8px;font-size:13px;line-height:1.6}.workflow-action .primary:disabled{background:#dce5e2;border-color:#dce5e2;color:#6f817b;cursor:not-allowed}.quote-skeleton{display:grid;gap:20px}.quote-skeleton span{height:56px;background:#e8eeee;border-radius:8px}@media(prefers-reduced-transparency:reduce){.workflow-action{background:#fff;backdrop-filter:none}}button:active{transform:scale(.98)}@media(prefers-reduced-motion:reduce){button:active{transform:none}}
.assessment-facts{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:0 24px}.assessment-facts .vehicle-identity{grid-column:1/-1}.assessment-facts input[readonly]{color:var(--color-text,#20383c);background:var(--color-surface-muted,#f3f2ef);cursor:default;min-width:0;width:100%;box-sizing:border-box}.quotation .quote-total{font-size:26px;font-weight:700;font-variant-numeric:tabular-nums;margin-left:10px;letter-spacing:-.02em;color:var(--color-text,#20383c)}.quote-total small,.assessment-confirmation small{font-size:13px;font-weight:500;letter-spacing:0}.assessment-entry label{max-width:460px}.quotation .assessment-entry input{font-size:24px;font-weight:600;font-variant-numeric:tabular-nums;min-width:0}.quotation .assessment-entry input::placeholder{font-size:14px;font-weight:400}.assessment-confirmation{padding:8px 0 16px}.assessment-confirmation p{font-size:13px;color:var(--color-text-secondary,#536a6b);line-height:1.7}.assessment-confirmation strong{display:block;margin:16px 0 24px;font-size:36px;font-weight:700;color:var(--color-text,#20383c);font-variant-numeric:tabular-nums;overflow-wrap:anywhere}.assessment-confirmation .inline-error{color:#a7313c}.quotation input:focus-visible{outline:2px solid var(--color-accent,#35383b);outline-offset:3px}@media(max-width:600px){.assessment-facts{grid-template-columns:1fr}.quotation .quote-total{font-size:23px}.quotation summary{line-height:1.8}.assessment-entry label{max-width:100%}}
</style>
